/**
 * Parameter types for each tool, mapped by tool name
 */
export type ToolParams = {
  [PROBLEM_SCHEDULES_CANCEL_SCHEDULE]: ProblemSchedulesCancelScheduleParams;
  [PROBLEM_SCHEDULES_LIST_SCHEDULES]: ProblemSchedulesListSchedulesParams;
  [PROBLEM_SCHEDULES_PAUSE_SCHEDULE]: ProblemSchedulesPauseScheduleParams;
  [PROBLEM_SCHEDULES_REPORT_RUN]: ProblemSchedulesReportRunParams;
  [PROBLEM_SCHEDULES_RESUME_SCHEDULE]: ProblemSchedulesResumeScheduleParams;
  [PROBLEM_SCHEDULES_SET_SCHEDULE]: ProblemSchedulesSetScheduleParams;
  [PROBLEM_STATUS_TRANSITION]: ProblemStatusTransitionParams;
};

/**
 * Invokes a tool by name using the SDK. A tool whose bindingStatus is
 * unsupported_multipart uploads a file, which tool parameters cannot carry;
 * invokeTool throws for it without sending a request.
 *
 * @param sdk - The initialized SDK instance
 * @param toolName - The namespaced tool name (e.g., "auth.sendMagicLink")
 * @param params - The parameters for the tool
 * @returns The result of the tool invocation
 * @throws Error if the tool name is not recognized
 *
 * @example
 * ```typescript
 * const sdk = new FixtureSchedulesApiSDK({ baseUrl: 'https://api.example.com' });
 * const result = await invokeTool(sdk, 'auth.sendMagicLink', { email: 'user@example.com' });
 * ```
 */
export async function invokeTool<T extends ToolName>(
  sdk: FixtureSchedulesApiSDK,
  toolName: T,
  params: ToolParams[T]
): Promise<unknown> {
  switch (toolName) {
    case PROBLEM_SCHEDULES_CANCEL_SCHEDULE:
      return sdk.problem.schedules.cancelSchedule((params as ProblemSchedulesCancelScheduleParams).id, { name: (params as ProblemSchedulesCancelScheduleParams).name });
    case PROBLEM_SCHEDULES_LIST_SCHEDULES:
      return sdk.problem.schedules.listSchedules((params as ProblemSchedulesListSchedulesParams).id, { name: (params as ProblemSchedulesListSchedulesParams).name });
    case PROBLEM_SCHEDULES_PAUSE_SCHEDULE:
      return sdk.problem.schedules.pauseSchedule((params as ProblemSchedulesPauseScheduleParams).id, { name: (params as ProblemSchedulesPauseScheduleParams).name });
    case PROBLEM_SCHEDULES_REPORT_RUN:
      return sdk.problem.schedules.reportRun((params as ProblemSchedulesReportRunParams).id, { attempt: (params as ProblemSchedulesReportRunParams).attempt, name: (params as ProblemSchedulesReportRunParams).name, outcome: (params as ProblemSchedulesReportRunParams).outcome, run: (params as ProblemSchedulesReportRunParams).run });
    case PROBLEM_SCHEDULES_RESUME_SCHEDULE:
      return sdk.problem.schedules.resumeSchedule((params as ProblemSchedulesResumeScheduleParams).id, { name: (params as ProblemSchedulesResumeScheduleParams).name });
    case PROBLEM_SCHEDULES_SET_SCHEDULE:
      return sdk.problem.schedules.setSchedule((params as ProblemSchedulesSetScheduleParams).id, { after: (params as ProblemSchedulesSetScheduleParams).after, cron: (params as ProblemSchedulesSetScheduleParams).cron, every: (params as ProblemSchedulesSetScheduleParams).every, name: (params as ProblemSchedulesSetScheduleParams).name, timeZone: (params as ProblemSchedulesSetScheduleParams).timeZone });
    case PROBLEM_STATUS_TRANSITION:
      return sdk.problem.status.transition((params as ProblemStatusTransitionParams).id, { from: (params as ProblemStatusTransitionParams).from, to: (params as ProblemStatusTransitionParams).to });
    default:
      throw new Error(`Unknown tool: ${toolName}`);
  }
}

/**
 * Gets the tool definition for a given tool name
 */
export function getToolDefinition(toolName: ToolName): ToolDefinition {
  return toolDefinitions[toolName];
}

/**
 * Gets all tools that require authentication
 */
export function getAuthRequiredTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.requiresAuth);
}

/**
 * Gets all tools that don't require authentication
 */
export function getPublicTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => !t.requiresAuth);
}

/**
 * Gets all tools for a specific namespace
 */
export function getToolsForNamespace(namespace: string): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.namespace === namespace);
}

/**
 * Validates that params contain all required fields for a tool
 */
export function validateToolParams(toolName: ToolName, params: Record<string, unknown>): { valid: boolean; missing: string[] } {
  const tool = toolDefinitions[toolName];
  const required = tool.parameters.required || [];
  const missing = required.filter(field => !(field in params) || params[field] === undefined);
  return { valid: missing.length === 0, missing };
}
